package com.arena.pekaclient.chat;

import com.arena.pekaclient.config.AppleSettings;
import com.arena.pekaclient.config.ChatQolSettings;
import com.arena.pekaclient.config.ChatQolSettings.Appearance;
import com.arena.pekaclient.config.ChatQolSettings.Window;
import com.arena.pekaclient.gui.GuiLayoutToolkit;
import com.arena.pekaclient.render.GlobalFontManager;
import com.arena.pekaclient.render.UIRender;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.FontRenderer;
import net.minecraft.client.gui.GuiChat;
import net.minecraft.client.gui.GuiScreen;
import net.minecraft.client.gui.GuiUtilRenderComponents;
import net.minecraft.client.gui.ScaledResolution;
import net.minecraft.event.ClickEvent;
import net.minecraft.util.IChatComponent;
import net.minecraftforge.client.event.ClientChatReceivedEvent;
import net.minecraftforge.client.event.MouseEvent;
import net.minecraftforge.client.event.RenderGameOverlayEvent;
import net.minecraftforge.fml.common.gameevent.TickEvent;
import org.lwjgl.input.Keyboard;
import org.lwjgl.input.Mouse;
import java.lang.reflect.Method;
import java.util.List;
import java.util.Map;
import java.util.IdentityHashMap;

/** Runtime caller of {@link ChatPipeline}: it owns all incoming routing and all custom chat draw/input paths. */
public final class ChatRuntime {
    private static final ChatPipeline DEFAULT_ALL=new ChatPipeline(), DEFAULT_PARTY=new ChatPipeline(), DEFAULT_REPLY=new ChatPipeline(), CHAT1=new ChatPipeline(), CHAT2=new ChatPipeline();
    private static final GuiLayoutToolkit.Rect defaultBox=new GuiLayoutToolkit.Rect(), chat1Box=new GuiLayoutToolkit.Rect(), chat2Box=new GuiLayoutToolkit.Rect(), menuBox=new GuiLayoutToolkit.Rect(), dragBox=new GuiLayoutToolkit.Rect();
    private static final Map<ChatPipeline.Row,IChatComponent> CLICK_COMPONENTS=new IdentityHashMap<ChatPipeline.Row,IChatComponent>(); private static final ChatContextMenu MENU_STATE=new ChatContextMenu(); private static ChatPipeline menuPipe; private static ChatPipeline.Message menuMessage; private static int menuTarget=-1; private static String toast=""; private static long toastUntil; private static int messageId; private static int draggingTarget=-1; private static float dragDX,dragDY; private static long lastUpdateNanos=System.nanoTime();
    private ChatRuntime(){}
    public static void reset(){DEFAULT_ALL.clear();DEFAULT_PARTY.clear();DEFAULT_REPLY.clear();CHAT1.clear();CHAT2.clear();menuPipe=null;menuMessage=null;draggingTarget=-1;}
    public static String selfTestStatus(){return "READY (Default/Chat 1/Chat 2 share ChatPipeline)";}
    public static void onChat(ClientChatReceivedEvent event){if(event==null||event.type==2||!ChatQolSettings.isEnabled()||event.message==null)return;IChatComponent c=event.message;String formatted=c.getFormattedText(), plain=c.getUnformattedText();ChatPipeline.Message m=new ChatPipeline.Message(c,formatted,plain,++messageId,nowTicks());DEFAULT_ALL.add(m);if(isParty(plain))DEFAULT_PARTY.add(m);if(isReply(plain))DEFAULT_REPLY.add(m);if(ChatQolSettings.separateChats){if(isParty(plain))CHAT1.add(m);else if(isReply(plain))CHAT2.add(m);}}
    public static void onRender(RenderGameOverlayEvent.Chat event){if(event==null||!ChatQolSettings.isEnabled())return;event.setCanceled(true);CLICK_COMPONENTS.clear();Minecraft mc=Minecraft.getMinecraft();if(mc==null)return;ScaledResolution sr=event.resolution;int sw=sr.getScaledWidth(),sh=sr.getScaledHeight();boolean open=mc.currentScreen instanceof GuiChat;layoutBoxes(sw,sh);long tick=nowTicks();ChatPipeline p=activeDefault();p.setOpen(open);renderPipe(p,ChatQolSettings.TARGET_DEFAULT,defaultBox,sw,sh,tick,open,false);if(ChatQolSettings.separateChats){CHAT1.setOpen(open);CHAT2.setOpen(open);renderPipe(CHAT1,ChatQolSettings.TARGET_CHAT_1,chat1Box,sw,sh,tick,open,true);renderPipe(CHAT2,ChatQolSettings.TARGET_CHAT_2,chat2Box,sw,sh,tick,open,true);}renderToast(sw,sh);}
    /** Called by PekaClientMod from the one Forge mouse event; there is no second wheel consumer. */
    public static void onMouse(MouseEvent ignored){if(!ChatQolSettings.isEnabled())return;Minecraft mc=Minecraft.getMinecraft();if(mc==null)return;ScaledResolution sr=new ScaledResolution(mc);float mx=mouseX(sr),my=mouseY(sr);layoutBoxes(sr.getScaledWidth(),sr.getScaledHeight());int wheel=Mouse.getEventDWheel();if(wheel!=0){ChatPipeline p=pipeAt(mx,my);if(p!=null){p.wheel(wheel,Keyboard.isKeyDown(Keyboard.KEY_LSHIFT)||Keyboard.isKeyDown(Keyboard.KEY_RSHIFT),AppleSettings.chatScrollMultiplier());if(ignored!=null)ignored.setCanceled(true);}return;}int button=Mouse.getEventButton();if(button<0)return;boolean down=Mouse.getEventButtonState();if(button==0&&down){if(beginMenuClick(mx,my))return;if(handleTabClick(mx,my))return;beginDrag(mx,my);ChatPipeline.Hit h=hitAt(mx,my);if(h!=null)forwardComponent(h);}else if(button==0&&!down){if(releaseMenuClick(mx,my))return;}else if(button==1&&!down){ChatPipeline.Hit h=hitAt(mx,my);if(h!=null&&ChatQolSettings.rightClickMenu)openMenu(pipeAt(mx,my),h.message(),targetAt(mx,my),mx,my,sr);else if(menuPipe!=null)closeMenu();}}
    public static void onTick(TickEvent.ClientTickEvent event){if(event==null||event.phase!=TickEvent.Phase.END)return;GlobalFontManager.tick();long n=System.nanoTime();float seconds=Math.min(.1f,Math.max(0,(n-lastUpdateNanos)/1000000000f));lastUpdateNanos=n;boolean smooth=AppleSettings.smoothScrolling;DEFAULT_ALL.update(seconds,smooth);DEFAULT_PARTY.update(seconds,smooth);DEFAULT_REPLY.update(seconds,smooth);CHAT1.update(seconds,smooth);CHAT2.update(seconds,smooth);if(draggingTarget>=0){Minecraft mc=Minecraft.getMinecraft();if(mc==null||!Mouse.isButtonDown(0)){draggingTarget=-1;return;}ScaledResolution sr=new ScaledResolution(mc);dragTo(mouseX(sr),mouseY(sr),sr.getScaledWidth(),sr.getScaledHeight());}}
    private static void renderPipe(ChatPipeline pipe,int target,GuiLayoutToolkit.Rect box,int sw,int sh,long tick,boolean open,boolean titled){Appearance a=ChatQolSettings.appearance(target);FontRenderer fr=GlobalFontManager.rendererFor(Minecraft.getMinecraft().fontRendererObj);float scale=Math.max(.5f,Math.min(2f,a.textScale()/100f));int title=titled?12:0;int usableW=Math.max(12,(int)((box.w-8)/scale));int row=Math.max(8,Math.round((fr.FONT_HEIGHT+a.lineSpacing())*scale));pipe.setLimit(target==ChatQolSettings.TARGET_CHAT_1?ChatQolSettings.chat1().getMessageLimit():target==ChatQolSettings.TARGET_CHAT_2?ChatQolSettings.chat2().getMessageLimit():100);final Map<ChatPipeline.Message,List<IChatComponent>> splitComponents=new IdentityHashMap<ChatPipeline.Message,List<IChatComponent>>();pipe.layout((int)box.x+4,(int)box.y+title+3,(int)box.w-8,(int)box.h-title-6,usableW,row,0,new ChatPipeline.Wrapper(){public List<String> wrap(String s,int w){return fr.listFormattedStringToWidth(s,w);}});for(ChatPipeline.Block block:pipe.blocks()){if(block.message.component instanceof IChatComponent){List<IChatComponent> split=GuiUtilRenderComponents.splitText((IChatComponent)block.message.component,usableW,fr,false,false);splitComponents.put(block.message,split);for(ChatPipeline.Row line:block.rows())if(line.line<split.size())CLICK_COMPONENTS.put(line,split.get(line.line));}}float sf=new ScaledResolution(Minecraft.getMinecraft()).getScaleFactor();UIRender.beginFrame();if(titled){UIRender.shadow(box.x,box.y,box.w,box.h,Math.max(2,a.radius()));UIRender.roundRectBorder(box.x,box.y,box.w,box.h,Math.max(2,a.radius()),alpha(a.backgroundColor(),a.backgroundOpacity()),alpha(a.backgroundColor(),a.backgroundOpacity()),alpha(a.borderColor(),a.borderOpacity()));UIRender.text(fr,target==ChatQolSettings.TARGET_CHAT_1?ChatQolSettings.chat1().getName():ChatQolSettings.chat2().getName(),box.x+5,box.y+2,0xFFEAEAF0,1f,true);}else if(a.backgroundOpacity()>0){UIRender.roundRect(box.x,box.y,box.w,box.h,a.radius(),alpha(a.backgroundColor(),a.backgroundOpacity()),alpha(a.backgroundColor(),a.backgroundOpacity()),1f);}UIRender.scissorBegin(pipe.viewport().x,pipe.viewport().y,pipe.viewport().w,pipe.viewport().h,sf);ChatPipeline.Hit hover=pipe.hit(mouseX(new ScaledResolution(Minecraft.getMinecraft())),mouseY(new ScaledResolution(Minecraft.getMinecraft())));for(ChatPipeline.Block block:pipe.blocks()){float fade=pipe.fadeAlpha(block.message,tick,a.fadeSeconds());if(fade<=0)continue;if(ChatQolSettings.hoverHighlight&&hover!=null&&hover.message()==block.message)UIRender.roundRect(block.bounds.x,block.bounds.y,block.bounds.w,block.bounds.h,Math.max(2,a.radius()),alpha(a.hoverColor(),a.hoverOpacity()),alpha(a.hoverColor(),a.hoverOpacity()),2f);for(ChatPipeline.Row row:block.rows()){UIRender.alphaMul=fade;UIRender.text(fr,row.formatted,row.bounds.x+1,row.bounds.y,0xFF000000|a.textColor(),scale,a.shadow());UIRender.alphaMul=1f;}}UIRender.scissorEnd();if(pipe.scroll().maximum()>0){float rail=box.h-title-8,thumb=Math.max(10,rail*Math.min(1f,pipe.viewport().h/(pipe.viewport().h+pipe.scroll().maximum()))),y=box.y+title+4+(rail-thumb)*(pipe.scroll().value()/pipe.scroll().maximum());UIRender.roundRect(box.x+box.w-3,y,2,thumb,1,0x8890A0B0,0x8890A0B0,1f);}if(target==ChatQolSettings.TARGET_DEFAULT&&open&&ChatQolSettings.tabsEnabled)drawTabs(fr,box);if(menuTarget==target)drawMenu(fr);UIRender.endFrame();}
    private static void drawTabs(FontRenderer fr,GuiLayoutToolkit.Rect b){int[] tabs={ChatQolSettings.TAB_ALL,ChatQolSettings.TAB_PARTY,ChatQolSettings.TAB_REPLY};String[] names={"All","Party","Reply"};float x=b.x;for(int i=0;i<3;i++){if(!ChatQolSettings.isTabVisible(tabs[i]))continue;float w=fr.getStringWidth(names[i])+12;int c=tabs[i]==ChatQolSettings.selectedTab?0xCC64D2FF:0x88242B35;UIRender.roundRect(x,b.y-13,w,11,3,c,c,1f);UIRender.text(fr,names[i],x+6,b.y-11,0xFFFFFFFF,1f,true);x+=w+3;}}
    private static boolean handleTabClick(float mx,float my){
        Minecraft mc=Minecraft.getMinecraft(); if(!(mc.currentScreen instanceof GuiChat)||!ChatQolSettings.tabsEnabled||!defaultBox.contains(mx,my+13))return false;
        FontRenderer fr=mc.fontRendererObj; int[] tabs={ChatQolSettings.TAB_ALL,ChatQolSettings.TAB_PARTY,ChatQolSettings.TAB_REPLY}; String[] names={"All","Party","Reply"}; float x=defaultBox.x;
        for(int i=0;i<3;i++){if(!ChatQolSettings.isTabVisible(tabs[i]))continue;float w=fr.getStringWidth(names[i])+12;if(mx>=x&&mx<x+w&&my>=defaultBox.y-13&&my<defaultBox.y-2){ChatQolSettings.setSelectedTab(tabs[i]);return true;}x+=w+3;}return false;
    }
    private static void drawMenu(FontRenderer fr){if(menuPipe==null||menuMessage==null)return;UIRender.shadow(menuBox.x,menuBox.y,menuBox.w,menuBox.h,4);UIRender.roundRectBorder(menuBox.x,menuBox.y,menuBox.w,menuBox.h,4,0xF022252C,0xF022252C,0xFF59616E);UIRender.text(fr,ChatContextMenu.OPTIONS[0],menuBox.x+7,menuBox.y+5,0xFFFFFFFF,1f,false);UIRender.text(fr,ChatContextMenu.OPTIONS[1],menuBox.x+7,menuBox.y+17,0xFFFFFFFF,1f,false);}
    private static void renderToast(int sw,int sh){if(toast.length()==0||System.currentTimeMillis()>toastUntil){toast="";return;}FontRenderer fr=Minecraft.getMinecraft().fontRendererObj;float w=fr.getStringWidth(toast)+16;UIRender.beginFrame();UIRender.roundRect(sw-w-8,sh-26,w,18,4,0xE022252C,0xE022252C,2);UIRender.text(fr,toast,sw-w,sh-22,0xFFFFFFFF,1f,false);UIRender.endFrame();}
    private static void openMenu(ChatPipeline pipe,ChatPipeline.Message message,int target,float x,float y,ScaledResolution sr){menuPipe=pipe;menuMessage=message;menuTarget=target;float w=Math.max(142,Minecraft.getMinecraft().fontRendererObj.getStringWidth(ChatClipboard.COPY_TO_CHAT_BOX)+14);GuiLayoutToolkit.clampPanel(menuBox,x,y,w,30,sr.getScaledWidth(),sr.getScaledHeight());}
    /** Context actions are armed on press and executed only when the matching option is released. */
    private static boolean beginMenuClick(float x,float y){if(menuPipe==null||!menuBox.contains(x,y))return false;MENU_STATE.press(y<menuBox.y+15?0:1);return true;}
    private static boolean releaseMenuClick(float x,float y){if(!MENU_STATE.armed())return false;int option=menuPipe!=null&&menuBox.contains(x,y)?(y<menuBox.y+15?0:1):-1;int chosen=MENU_STATE.release(option);if(chosen<0){closeMenu();return true;}ChatPipeline.Message m=menuMessage;closeMenu();if(chosen==0){ChatClipboard.Result r=ChatClipboard.copy(m.plain);toast(r.success?"Copied to clipboard":"Could not copy to clipboard");}else{Minecraft.getMinecraft().displayGuiScreen(new GuiChat(m.plain));toast("Copied to chat box");}return true;}
    private static void closeMenu(){menuPipe=null;menuMessage=null;menuTarget=-1;MENU_STATE.clear();}
    private static void toast(String s){toast=s==null?"":s;toastUntil=System.currentTimeMillis()+2200L;}
    private static void beginDrag(float x,float y){if(!ChatQolSettings.separateChats)return;int target=-1;if(titleAt(chat1Box,x,y))target=ChatQolSettings.TARGET_CHAT_1;else if(titleAt(chat2Box,x,y))target=ChatQolSettings.TARGET_CHAT_2;if(target<0)return;GuiLayoutToolkit.Rect b=target==ChatQolSettings.TARGET_CHAT_1?chat1Box:chat2Box;draggingTarget=target;dragDX=x-b.x;dragDY=y-b.y;}
    private static boolean titleAt(GuiLayoutToolkit.Rect b,float x,float y){return x>=b.x&&x<b.x+b.w&&y>=b.y&&y<b.y+12;}
    private static void dragTo(float x,float y,int sw,int sh){Window w=draggingTarget==ChatQolSettings.TARGET_CHAT_1?ChatQolSettings.chat1():ChatQolSettings.chat2();float ww=Math.max(80,sw*w.getW()/100f),hh=Math.max(50,sh*w.getH()/100f);GuiLayoutToolkit.clampPanel(dragBox,x-dragDX,y-dragDY,ww,hh,sw,sh);if(ChatQolSettings.snapWindows){float snap=8f;if(Math.abs(dragBox.x)<snap)dragBox.x=0;if(Math.abs(dragBox.y)<snap)dragBox.y=0;if(Math.abs((sw-dragBox.w)-dragBox.x)<snap)dragBox.x=sw-dragBox.w;if(Math.abs((sh-dragBox.h)-dragBox.y)<snap)dragBox.y=sh-dragBox.h;}w.setGeometry(Math.round(dragBox.x*100f/sw),Math.round(dragBox.y*100f/sh),Math.round(dragBox.w*100f/sw),Math.round(dragBox.h*100f/sh));AppleSettings.save();}
    private static void layoutBoxes(int sw,int sh){defaultBox.set(2,Math.max(6,sh-(Minecraft.getMinecraft().currentScreen instanceof GuiChat?180:92)),Math.min(320,sw-4),Minecraft.getMinecraft().currentScreen instanceof GuiChat?164:82);windowBox(chat1Box,ChatQolSettings.chat1(),sw,sh);windowBox(chat2Box,ChatQolSettings.chat2(),sw,sh);}
    private static void windowBox(GuiLayoutToolkit.Rect out,Window w,int sw,int sh){GuiLayoutToolkit.clampPanel(out,sw*w.getX()/100f,sh*w.getY()/100f,Math.max(80,sw*w.getW()/100f),Math.max(50,sh*w.getH()/100f),sw,sh);}
    private static ChatPipeline activeDefault(){return ChatQolSettings.selectedTab==ChatQolSettings.TAB_PARTY?DEFAULT_PARTY:ChatQolSettings.selectedTab==ChatQolSettings.TAB_REPLY?DEFAULT_REPLY:DEFAULT_ALL;}
    private static ChatPipeline pipeAt(float x,float y){if(menuPipe!=null&&menuBox.contains(x,y))return null;if(defaultBox.contains(x,y))return activeDefault();if(ChatQolSettings.separateChats){if(chat1Box.contains(x,y))return CHAT1;if(chat2Box.contains(x,y))return CHAT2;}return null;}
    private static int targetAt(float x,float y){if(defaultBox.contains(x,y))return ChatQolSettings.TARGET_DEFAULT;if(chat1Box.contains(x,y))return ChatQolSettings.TARGET_CHAT_1;if(chat2Box.contains(x,y))return ChatQolSettings.TARGET_CHAT_2;return -1;}
    private static ChatPipeline.Hit hitAt(float x,float y){ChatPipeline p=pipeAt(x,y);return p==null?null:p.hit(x,y);}
    private static void forwardComponent(ChatPipeline.Hit hit){if(hit==null||hit.message()==null||!(hit.message().component instanceof IChatComponent))return;IChatComponent c=CLICK_COMPONENTS.get(hit.row);if(c==null)c=(IChatComponent)hit.message().component;ClickEvent e=c.getChatStyle()==null?null:c.getChatStyle().getChatClickEvent();if(e==null)return;try{GuiScreen screen=Minecraft.getMinecraft().currentScreen;if(screen!=null){Method m=GuiScreen.class.getDeclaredMethod("handleComponentClick",IChatComponent.class);m.setAccessible(true);m.invoke(screen,c);return;}}catch(Throwable ignored){}try{if(e.getAction()==ClickEvent.Action.RUN_COMMAND)Minecraft.getMinecraft().thePlayer.sendChatMessage(e.getValue());else if(e.getAction()==ClickEvent.Action.SUGGEST_COMMAND)Minecraft.getMinecraft().displayGuiScreen(new GuiChat(e.getValue()));}catch(Throwable ignored){}}
    private static boolean isParty(String s){String v=s==null?"":s.toLowerCase(java.util.Locale.ROOT);return v.contains("party >")||v.contains("party chat")||v.contains("[party]");}
    private static boolean isReply(String s){String v=s==null?"":s.toLowerCase(java.util.Locale.ROOT);return v.startsWith("from ")||v.startsWith("to ")||v.contains(" whispers:")||v.contains(" reply");}
    private static long nowTicks(){Minecraft mc=Minecraft.getMinecraft();return mc!=null&&mc.theWorld!=null?mc.theWorld.getTotalWorldTime():System.currentTimeMillis()/50L;}
    private static int alpha(int rgb,int pct){return (Math.max(0,Math.min(100,pct))*255/100<<24)|(rgb&0xFFFFFF);}private static float mouseX(ScaledResolution s){Minecraft m=Minecraft.getMinecraft();return Mouse.getX()*s.getScaledWidth()/(float)m.displayWidth;}private static float mouseY(ScaledResolution s){Minecraft m=Minecraft.getMinecraft();return s.getScaledHeight()-Mouse.getY()*s.getScaledHeight()/(float)m.displayHeight-1;} 
}
